  "head" : {
    "vars" : [ "label", "description", "qid" ]
  },
  "results" : {
    "bindings" : [ {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "susceptible infectious susceptible model"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "continuous-time model for the spreading of infectious diseases with temporary resistance considering susceptible and infectious individuals"
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6675171"
      }
    } ]
  }
}

request.data:
SELECT DISTINCT ?label ?description ?qid
WHERE {
  ?model wdt:P31 wd:Q68663 ;
         rdfs:label ?label .
  FILTER(LANG(?label) = "en")
  # formula: rate of change of infectious in the SIS model
  {
    ?model p:P1674 ?formula_assumes_statement_0 .
    ?formula_assumes_statement_0 ps:P1674 wd:Q6674293 .
  }
  UNION
  {
    ?model p:P1560 ?formula_contains_statement_0 .
    ?formula_contains_statement_0 ps:P1560 wd:Q6674293 .
  }
  OPTIONAL { ?model schema:description ?description . FILTER(LANG(?description) = "en") }
  BIND(STRAFTER(STR(?model), STR(wd:)) AS ?qid)
}
ORDER BY LCASE(?label)
LIMIT 101
